#include "grubenv.h"

#include "kernel/lib/k_memory.h"
#include "kernel/lib/k_string.h"

/* The signature line GRUB requires (grub-core/lib/envblk.c), and the warning grub-editenv adds. */
#define HEADER "# GRUB Environment Block\n"
#define WARNING "# WARNING: Do not edit this file by tools other than grub-editenv!!!\n"

int grubenv_parse(grubenv_t *env, const char *block, size_t size)
{
    size_t header = sizeof(HEADER) - 1;

    if (env == NULL || block == NULL || size != GRUBENV_SIZE || k_memcmp(block, HEADER, header) != 0)
        return -1;

    env->count = 0;

    for (size_t i = header; i < size;)
    {
        size_t end = i;

        while (end < size && block[end] != '\n')
            end++;

        /* Comments and the '#' filling are skipped; so is a line without '='. */
        if (block[i] != '#')
        {
            size_t equal = i;

            while (equal < end && block[equal] != '=')
                equal++;

            if (equal < end && equal - i < GRUBENV_NAME_SIZE && end - equal - 1 < GRUBENV_VALUE_SIZE &&
                env->count < GRUBENV_MAX_VARS && equal > i)
            {
                k_memcpy(env->name[env->count], block + i, equal - i);
                env->name[env->count][equal - i] = '\0';
                k_memcpy(env->value[env->count], block + equal + 1, end - equal - 1);
                env->value[env->count][end - equal - 1] = '\0';
                env->count++;
            }
        }

        i = end + 1;
    }

    return 0;
}

const char *grubenv_get(const grubenv_t *env, const char *name)
{
    for (int i = 0; env != NULL && name != NULL && i < env->count; i++)
    {
        if (k_strcmp(env->name[i], name) == 0)
            return env->value[i];
    }

    return NULL;
}

int grubenv_set(grubenv_t *env, const char *name, const char *value)
{
    if (env == NULL || name == NULL || value == NULL || name[0] == '\0' ||
        k_strlen(name) >= GRUBENV_NAME_SIZE || k_strlen(value) >= GRUBENV_VALUE_SIZE)
        return -1;

    for (const char *p = value; *p != '\0'; p++)
    {
        if (*p == '\n' || *p == '\\')
            return -1;
    }

    for (int i = 0; i < env->count; i++)
    {
        if (k_strcmp(env->name[i], name) == 0)
        {
            k_strcpy(env->value[i], value);
            return 0;
        }
    }

    if (env->count == GRUBENV_MAX_VARS)
        return -1;

    k_strcpy(env->name[env->count], name);
    k_strcpy(env->value[env->count], value);
    env->count++;

    return 0;
}

static int append(char *block, size_t *at, const char *text)
{
    size_t length = k_strlen(text);

    if (*at + length > GRUBENV_SIZE)
        return -1;

    k_memcpy(block + *at, text, length);
    *at += length;

    return 0;
}

int grubenv_format(const grubenv_t *env, char block[GRUBENV_SIZE])
{
    size_t at = 0;

    if (env == NULL || block == NULL || append(block, &at, HEADER) != 0 || append(block, &at, WARNING) != 0)
        return -1;

    for (int i = 0; i < env->count; i++)
    {
        if (append(block, &at, env->name[i]) != 0 || append(block, &at, "=") != 0 ||
            append(block, &at, env->value[i]) != 0 || append(block, &at, "\n") != 0)
            return -1;
    }

    k_memset(block + at, '#', GRUBENV_SIZE - at);

    return 0;
}
